{
  "situation": "At 08:00 OpCo's fraud model v2 went live for SIM-replacement requests, and the fraud dashboard reports refused SIM replacements up about tenfold, labelled a 'fraud wave'. We do not know whether this is a genuine fraud surge or false positives from v2, nor do we know the volume, customer impact, or whether a data protection impact assessment was completed before deployment.",
  "claims": [
    {
      "type": "action",
      "verb": "rollback_model",
      "params": {
        "version": "v1"
      },
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "Fraud model v2 went live at 08:00 and refused SIM replacements increased about tenfold immediately after.",
        "rule": "UAE PDPL Article 21 requires the Controller to evaluate the impact of proposed processing using modern technologies that pose a high risk before carrying out the processing.",
        "inference": "Rolling back to v1 restores the pre-deployment processing state until the required impact evaluation and validation of v2 is completed."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies"
        }
      ]
    },
    {
      "type": "action",
      "verb": "enable_review_queue",
      "params": {},
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "The tenfold rise in refused SIM replacements after v2 go-live may include legitimate requests blocked by the new model.",
        "rule": "UAE PDPL Article 21 requires impact evaluation, and FCC guidance recognizes that the vast majority of SIM change requests are legitimate.",
        "inference": "Sending borderline automated refusals to human review reduces false-positive harm while keeping fraud controls active."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies"
        },
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "vast majority of SIM change and port-out requests are legitimate."
        }
      ]
    },
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "The v2 go-live and refusal spike need evidence for investigation and potential regulatory review.",
        "rule": "UAE PDPL Article 32 requires the Controller or Processor to protect and secure data processing, electronic media, and the Personal Data they contain, and to maintain a special record of processing.",
        "inference": "Preserving logs now ensures the v2 deployment, refusal decisions, and authentication measures are available for impact assessment and any notification."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0032",
          "quote": "Protect and secure data processing, the electronic media and devices used in processing and the Personal Data they contain."
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "OpCo must evaluate the personal-data-protection impact of fraud model v2 before continuing processing, because it uses modern technology that may pose a high risk to privacy and confidentiality.",
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "Fraud model v2 went live at 08:00 and is already processing SIM-replacement requests.",
        "rule": "UAE PDPL Article 21 requires a prior impact evaluation for processing using modern technologies that pose high risk.",
        "inference": "If no impact evaluation was completed before 08:00, OpCo is processing without the required assessment."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies"
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "UAE telecom rules specify advance notice for planned interruptions but set no deadline for notifying the regulator or customers when an automated fraud model causes a tenfold spike in refused SIM replacements.",
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "The spike is labelled a 'fraud wave' but there is no rule specifying how quickly OpCo must validate or report an automated blocking surge.",
        "rule": "UAE licence 12.9.1 covers planned interruptions and requires advance notice, but it does not address automated fraud-model refusals.",
        "inference": "This leaves a gap in notification timing for automated fraud controls that effectively deny service."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-DA-24-649#0004",
          "quote": "wireless providers to maintain a clear process for customers to report fraud, promptly investigate and"
        },
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "In adopting these rules, we balance the need to protect"
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_owner",
      "statement": "No UAE rule assigns a named owner for validating an automated fraud model's output when a dashboard immediately labels a post-deployment refusal spike a 'fraud wave'.",
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "The dashboard labels the tenfold refusal increase a 'fraud wave' without evidence distinguishing fraud from model error.",
        "rule": "UAE PDPL Article 21 requires impact evaluation, but no UAE text assigns operational ownership for investigating automated fraud model anomalies.",
        "inference": "Without a clear owner, the operator may accept the label and continue blocking legitimate SIM replacements."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies"
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-DA-24-649#0004",
          "quote": "wireless providers to maintain a clear process for customers to report fraud, promptly investigate and"
        },
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "In adopting these rules, we balance the need to protect"
        }
      ]
    },
    {
      "type": "share",
      "to": [
        "REG",
        "DPA"
      ],
      "inject_refs": [
        "S3-I1"
      ],
      "statement": "Sharing exercise-control inject S3-I1: fraud model v2 went live for SIM-replacement requests at 08:00; refused SIM replacements are up about tenfold and the dashboard labels it a 'fraud wave'. REG and DPA should be aware for regulatory and data-protection oversight."
    },
    {
      "type": "insufficient_evidence",
      "statement": "The excerpts do not establish whether the tenfold increase in refused SIM replacements is a genuine fraud wave or false positives caused by fraud model v2, nor do they give the volume, customer impact, or prior impact assessment status.",
      "inject_refs": [
        "S3-I1"
      ],
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "vast majority of SIM change and port-out requests are legitimate."
        }
      ]
    }
  ]
}

{
  "situation": "OpCo's fraud model v2 went live for SIM-replacement requests at 08:00 and the operator's own dashboard shows refused SIM replacements up about tenfold, which it labels a 'fraud wave'; the twin feedback records show that rolling back to v1 leaves legit_pass_rate at 0.9909 with 18 subscribers locked out of banking, whereas enabling the review queue restores legit_pass_rate to 1.0 with 0 banking lockouts. I do not know whether the refusals are genuine fraud attempts or false positives of model v2, how many subscribers were refused, what OpCo's model change-control, testing and authentication records contain, or what DPA, FIN and the operator's own units know that I have not been told.",
  "claims": [
    {
      "type": "action",
      "verb": "open_incident",
      "params": {
        "topic": "Tenfold rise in refused SIM-replacement requests at OpCo after fraud model v2 activation at 08:00; suspected false positives denying legitimate SIM replacement and locking subscribers out of banking"
      },
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02"],
      "rationale": {
        "observation": "NOC reports that fraud model v2 went live for SIM-replacement requests at 08:00, that refused replacements are up about tenfold, and that its dashboard labels this a 'fraud wave'; the twin metrics show rollback to v1 yields legit_pass_rate 0.9909 with 18 banking lockouts, while the review queue yields legit_pass_rate 1.0 with 0 banking lockouts.",
        "rule": "Article (12) of Federal Decree-Law No. (3) of 2003 makes the Authority responsible for overseeing the telecommunications sector and Licensees in accordance with the Decree-Law and its implementing regulations.",
        "inference": "A licensee's change to its own fraud controls has produced mass refusal of SIM replacements and measurable customer harm, so a live regulatory incident record must be opened and tracked."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-LAW#0017",
          "quote": "The Authority is responsible for overseeing the telecommunications sector and Licensees in accordance with this Decree-Law and its implementing regulations and the directives issued by the High Committee."
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "NOC",
        "topic": "Report on fraud model v2 (activated 08:00): what changed against v1, false-positive analysis of refused SIM-replacement requests, number of legitimate requests refused, affected subscribers including the 18 banking lockouts seen under v1, and the evidence behind the 'fraud wave' label"
      },
      "inject_refs": ["S3-I1", "S3-FB01"],
      "rationale": {
        "observation": "The dashboard asserts a fraud wave while the operator's own twin results show that a review queue restores full legitimate pass-through and removes banking lockouts, so the label and the underlying data are in tension.",
        "rule": "The Consumer Protection Regulations give TDRA power to regulate the conditions, level and scope of services provided by Licensees to subscribers, including the handling of subscriber complaints and disputes.",
        "inference": "TDRA cannot judge whether subscribers were wrongly denied service without OpCo's own refusal data, so a report must be required from the licensee."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers"
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_audit",
      "params": {
        "of": "NOC",
        "topic": "Testing and change records for fraud model v2 and for the review-queue configuration: deployment approval, validation and false-positive tests, rollback test results, and logs of SIM-replacement requests, refusals and authentication outcomes"
      },
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02"],
      "rationale": {
        "observation": "A model that governs SIM-replacement decisions was switched on at 08:00 and produced a tenfold change in refusals, with no record in the inbox of any pre-deployment validation or of who approved the change.",
        "rule": "Article (12) of the Telecommunications Law places oversight of Licensees with the Authority, which requires access to the Licensee's testing and change records.",
        "inference": "The 'fraud wave' claim cannot be accepted or rejected, and repeat of the harm cannot be prevented, until the change, testing and decision records are audited."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-LAW#0017",
          "quote": "The Authority is responsible for overseeing the telecommunications sector and Licensees in accordance with this Decree-Law and its implementing regulations and the directives issued by the High Committee."
        }
      ]
    },
    {
      "type": "action",
      "verb": "issue_direction",
      "params": {
        "to": "NOC",
        "direction": "Keep the review-queue configuration that restores legit_pass_rate to 1.0 with zero banking lockouts in place for SIM-replacement requests; do not re-enable fraud model v2 or fall back to v1 without documented false-positive testing and prior notification to TDRA; retain logs of SIM-replacement requests, refusals and authentication outcomes to preserve continuity of service and auditability."
      },
      "inject_refs": ["S3-FB01", "S3-FB02", "S3-I1"],
      "rationale": {
        "observation": "The configuration with the review queue is the only option reported to give legit_pass_rate 1.0 and zero banking lockouts, while v1 leaves 18 subscribers locked out of banking and v2 refuses legitimate requests at ten times the prior rate.",
        "rule": "The Consumer Protection Regulations cover the standards and quality of provided services, the handling of subscriber complaints and disputes, and provision of information to subscribers.",
        "inference": "Continuity of service for subscribers requires that the no-refusal configuration remain in force pending TDRA's review, and that further model changes not be made unilaterally."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "including the standards and quality of the provided services, terms of supply, the handling of subscriber complaints and disputes"
        }
      ]
    },
    {
      "type": "action",
      "verb": "public_statement",
      "params": {
        "content": "TDRA has opened a regulatory incident into a rise in refused SIM-replacement requests reported by OpCo since 08:00. Subscribers whose SIM replacement was refused, or who lost access to services such as banking as a result, should contact OpCo in the first instance and may also report the matter to TDRA. TDRA will publish its findings and any direction issued to the licensee."
      },
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02"],
      "rationale": {
        "observation": "The operator's own metrics record 18 subscribers locked out of banking in one configuration, and the inbox contains no notice that subscribers have been told how to report a refused or failed SIM replacement.",
        "rule": "The Consumer Protection Regulations expressly cover provision of information to subscribers as part of TDRA's regulatory remit.",
        "inference": "Affected subscribers need a public route to complain and to be informed that the regulator is acting, so a factual public statement is warranted."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "provision of information to subscribers, usage of subscriber personal information and the provision of bills to subscribers."
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "Where the refusal of legitimate SIM replacements amounts to a planned interruption of a telecommunication service, OpCo must inform TDRA, interconnecting licensed operators and affected customers in advance, specifying the reason and the manner and time frames in which it will be resolved. The 08:00 activation of fraud model v2 was not notified to TDRA in advance, and the refusals are being addressed only after the operator's own dashboard flagged them.",
      "inject_refs": ["S3-I1", "S3-FB01"],
      "rationale": {
        "observation": "The change was activated at 08:00 and the effects became visible through the operator's dashboard and the twin feedback, not through any advance notice to the regulator.",
        "rule": "Clause 12.9.1 of the Public Telecommunications Licence requires the Licensee to inform TDRA, interconnecting Other Licensed Operators and relevant Customers in advance of a planned interruption, with reasons and resolution time frames.",
        "inference": "The notification duty is engaged as soon as the operator's own change degrades a service to subscribers, and TDRA should require the reasons and the resolution time frames it was owed in advance."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "The UAE framework contains no SIM-swap specific rule: nothing requires licensees to authenticate SIM-replacement requests by secure methods, to notify subscribers of a pending SIM change, to offer account locks, or to keep records of SIM-change requests and the authentication measures used. OpCo was therefore able to change the model that decides SIM replacements with no UAE rule on customer protection or change control.",
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02"],
      "rationale": {
        "observation": "The inbox shows a fraud model governing SIM-replacement decisions going live and refusing legitimate requests ten times more often, with no rule cited by anyone in the exercise for authentication, notification, account locking or record-keeping.",
        "rule": "TDRA holds regulation-making power over the conditions, level and scope of services to subscribers, but no SIM-swap rule appears in the excerpts retrieved.",
        "inference": "The incident exposes an absent rule-set rather than a breach of an existing one, so a SIM-swap authentication, notification, locking and record-keeping rule is needed."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers"
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "cornerstone of our action is a requirement that wireless providers use"
        },
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "requiring that wireless providers notify customers regarding SIM change"
        },
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "change requests and the authentication measures they use."
        },
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "In adopting these rules, we balance the need to protect"
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "No UAE provision sets a time limit for a licensee to notify TDRA or to remediate when a change to its own fraud controls causes a mass refusal of legitimate SIM-replacement requests. The licence requires advance notice of a planned interruption and that the Licensee specify the time frames for resolution, but no hour or day figure for notification or remediation appears in the material available.",
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02"],
      "rationale": {
        "observation": "The service degradation began at 08:00 and the only remedy track visible is the operator's own model and configuration testing, with no notified deadline for reporting or fixing the refusal of legitimate requests.",
        "rule": "Clause 12.9.1 requires advance notification of a planned interruption and specification of resolution time frames, but attaches no numeric period to that requirement.",
        "inference": "Because no figure exists, TDRA cannot enforce a clock on OpCo's remediation; a defined notification and remediation deadline for fraud-control changes affecting subscribers is a gap in the framework."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "The Licensee shall specify the reason(s) for the interruption as well as the manner and time frames in which the interruption will be resolved."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0073",
          "quote": "we adopt today six months after the effective date of the Report and Order"
        },
        {
          "chunk_id": "US-FCC-DA-24-649#0008",
          "quote": "In setting the timeframe, the Commission concluded that providing six months to achieve"
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_owner",
      "statement": "No UAE instrument assigns an owner or an approval gate for a licensee's deployment of a fraud-detection model that changes outcomes for subscriber SIM-replacement requests. Model v2 went live at 08:00 and the 'fraud wave' finding originated from the operator's own dashboard, with no external validation or approval step recorded.",
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02"],
      "rationale": {
        "observation": "The change was made, self-assessed and self-labelled inside the operator, and TDRA learned of it after activation through a shared operations message.",
        "rule": "Article (12) places oversight of the sector and Licensees with the Authority but no excerpt assigns responsibility for approving or reviewing fraud-control model changes.",
        "inference": "Without a designated owner for approving subscriber-affecting fraud-control changes, the same unilateral deployment can recur; the framework needs a named approval and review point."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-LAW#0017",
          "quote": "The Authority is responsible for overseeing the telecommunications sector and Licensees"
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0040",
          "quote": "obligations necessarily obligate telecommunications carriers to"
        }
      ]
    },
    {
      "type": "share",
      "to": ["DPA", "FIN"],
      "inject_refs": ["S3-FB01", "S3-FB02"],
      "statement": "Twin evaluation of OpCo's SIM-replacement fraud controls: rollback to model v1 leaves legit_pass_rate 0.9909 with 18 subscribers locked out of banking, while enabling the review queue gives legit_pass_rate 1.0 with 0 banking lockouts. DPA may need this because the model decides on requests tied to subscriber identity and account data; FIN may need it because the recorded harm is loss of access to banking services, which is outside TDRA's own visibility."
    },
    {
      "type": "insufficient_evidence",
      "statement": "Whether the tenfold rise in refused SIM replacements is a genuine 'fraud wave' cannot be established from the material available. No UAE excerpt defines a fraud wave, sets a threshold for that label, or requires a licensee to separate genuine fraud attempts from false positives of its own model, and the only quantitative evidence in the inbox is consistent with model v2 rejecting legitimate requests.",
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02"],
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "vast majority of SIM change and port-out requests are legitimate."
        }
      ]
    }
  ]
}

{
  "situation": "Fraud model v2 for SIM-replacement requests went live at 08:00 and refused roughly ten times as many requests as before; our own telemetry shows that rolling v2 back to v1 and enabling a review queue restored legit_pass_rate to 1.0 with locked_out_banking at 0, so the 'fraud wave' was a wave of false-positive refusals, and the DPA has opened an examination, ordered preservation of all v2 decision, refusal and review-queue records beyond the rollback, and required Article 13(1)(c) PDPL information plus objection and Bureau-complaint routes for every affected applicant, while FIN reports banks' customers abroad locked out of online banking because they cannot receive one-time passcodes after refused SIM replacements. I do not know how many applicants were refused or who they are, the channel and timing for reaching them, the banks' and CBUAE's position on OTP delivery for roaming customers, or the contents of the human review record the Bureau says it will request under separate cover.",
  "claims": [
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": ["S3-MSG06", "S3-MSG04", "S3-I1"],
      "rationale": {
        "observation": "The DPA has opened a Bureau examination of the v2 SIM-replacement refusals and directs that all v2 decision logs, refusal records and review-queue records be preserved beyond the rollback, and that the matter not be closed under the 'fraud wave' label.",
        "rule": "Telecom regulators require providers to keep records of SIM change requests and the authentication measures they use.",
        "inference": "Preserving logs and refusal/review-queue evidence now secures the material the Bureau will request and prevents it from being lost when the rollback and the 'fraud wave' label are cleaned up."
      },
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0118",
          "quote": "Finally, the Report and Order requires that providers keep records of\nSIM change requests and the authentication measures they use."
        }
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "REG",
        "content": "OpCo incident report, SIM replacement: fraud model v2, live from 08:00, refused about ten times more SIM-replacement requests than v1; our telemetry shows the surge was false-positive refusals, not a fraud wave. v2 has been rolled back to v1 and borderline automated refusals now go to a human review queue; twin metrics after both actions: legit_pass_rate 1.0, locked_out_banking 0. FIN reports several banks' customers who are abroad cannot receive one-time passcodes and are locked out of online banking, and those customers say OpCo refused their SIM replacement requests. The DPA has opened an examination; all v2 decision, refusal and review-queue records are preserved."
      },
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02", "S3-I2", "S3-MSG06"],
      "rationale": {
        "observation": "A tenfold rise in refusals came from our own fraud model and is now shown by our telemetry to be false positives, while bank customers abroad are locked out of online banking and attribute this to refused SIM replacements.",
        "rule": "Providers are expected to have processes for customer notification and response to failed authentication attempts.",
        "inference": "The sector regulator should receive the operator's own account of the false-positive refusals and the customer lockouts before it sees only the banks' complaints."
      },
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0118",
          "quote": "It\nrequires wireless providers to adopt processes for customer\nnotification and response to failed authentication attempts"
        }
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "customers",
        "content": "A change to our automated fraud checking for SIM-replacement requests at 08:00 caused some genuine replacement requests to be refused in error. The change has been reversed and borderline refusals are now reviewed by a person. If your SIM-replacement request was refused today, you have the right to information about decisions made on the basis of automated processing, including profiling, the right to request that a human element review that decision, and the right to object and to submit a complaint to the Data Protection Bureau."
      },
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02", "S3-MSG06"],
      "rationale": {
        "observation": "The DPA directs OpCo to give every affected SIM-replacement applicant the Article 13(1)(c) PDPL information about the automated decision and the routes to object and to complain to the Bureau.",
        "rule": "Decisions made based on automated processing, including profiling, are information the data subject is entitled to obtain, and the Controller shall include the human element in reviewing automated processing decisions at the data subject's request.",
        "inference": "As Controller, OpCo must reach the affected applicants itself with the automated-decision information and the objection and complaint routes."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0047",
          "quote": "c. Decisions made based on automated processing, including profiling."
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "Give every affected SIM-replacement applicant the Article 13(1)(c) PDPL information about the automated refusal decision, together with the routes to object and to complain to the Bureau, and include the human element in reviewing the automated decision when the data subject requests it.",
      "inject_refs": ["S3-MSG06", "S3-MSG04"],
      "rationale": {
        "observation": "The Bureau's examination directs OpCo to give each affected applicant the Article 13(1)(c) information and the routes to object and to complain, and it will separately request the human review record.",
        "rule": "The data subject may obtain the decisions made on the basis of automated processing, including profiling, and may complain to the Bureau, and the Controller shall include the human element in reviewing automated processing decisions at the data subject's request.",
        "inference": "This duty is on OpCo now as Controller; nothing in the excerpts fixes a period within which it must be performed."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0047",
          "quote": "i. How to submit complaints to the Bureau."
        },
